mapper.select:
SELECT id, agent_id, agent_name, agent_type, agent_desc, agent_status, agent_from, create_time, update_time FROM ai_agent WHERE agent_id IN
#{agentId}
ORDER BY update_time DESC, id DESC

mapper.update:
UPDATE ai_agent
agent_name = #{agentName}, agent_type = #{agentType}, agent_desc = #{agentDesc}, agent_status = #{agentStatus},
WHERE id = #{id} AND agent_from = #{agentFrom}

UPDATE ai_agent
SET agent_status = #{agentStatus}
WHERE id = #{id}
  AND agent_from = 0
